package dev.resilience4cata.generated;

import dev.resilience4cata.internal.RegistryAccess;

/**
 * The generated-code level this core supports. Every generated class calls {@link #require} first in each of its
 * constructors with the level of the processor that wrote it, so that code generated by a newer processor than the
 * core on the class path fails at once, with a clear message ({@code R4C-RT-021}), instead of with a
 * {@code NoSuchMethodError} on its first failure in production.
 *
 * <p>Within a major version, code generated by processor {@code 1.a} runs on core {@code 1.b} for every
 * {@code b >= a}. The level goes up when the processor starts emitting a call that older cores do not have; it never
 * goes down, and every member of this package that generated code of a supported level calls stays, binary
 * compatible.
 */
public final class Abi {

    /** The highest level this core supports. Not a public constant: it would be inlined into callers. */
    private static final int LEVEL = 2;

    private Abi() {
    }

    /**
     * Checks that this core runs code of {@code level}.
     *
     * @param level the level of the processor that generated {@code generated}
     * @param generated the generated class
     * @throws IllegalStateException {@code R4C-RT-021} if this core is too old for it
     */
    public static void require(int level, Class<?> generated) {
        if (level > LEVEL) {
            throw tooOld("resilience4cata-core", generated, level, LEVEL);
        }
    }

    /**
     * The {@code R4C-RT-021} exception, for this core or for another runtime module (the reactor module's check).
     *
     * @param component the artifact that is too old
     * @param generated the generated class
     * @param level the level it needs
     * @param supported the level {@code component} supports
     * @return the exception, to throw
     */
    public static IllegalStateException tooOld(String component, Class<?> generated, int level, int supported) {
        return RegistryAccess.get().runtimeTooOld(component, generated, level, supported);
    }
}
